package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;

/** Lazy, offline Play activities. No licensed character assets, services or network permissions. */
public final class FreedomPlayActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());
    private FreedomChess chess;private Board board;private Skyhop sky;private LinearLayout body;private TextView message;private String mode="menu",profile;private int generation,level=2;private boolean active;
    @Override protected void attachBaseContext(Context c){super.attachBaseContext(LauncherLocale.wrap(c));}
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);ProductFeatures.init(this);Config.load(this);profile=ProfileStore.id();menu();}
    private android.content.SharedPreferences store(){return getSharedPreferences(LocalProfiles.filename(profile,"cinema-play"),0);}
    private void layout(String title,String subtitle){if(sky!=null)sky.running=false;sky=null;board=null;LinearLayout root=FreedomUi.body(this);root.setBackgroundColor(0xff101822);setContentView(root);root.addView(FreedomUi.text(this,"DV FREEDOM  /  PLAY",13));root.addView(FreedomUi.text(this,title,28));TextView help=FreedomUi.text(this,subtitle,16);help.setTextColor(0xffb4c5d6);root.addView(help);ScrollView scroll=new ScrollView(this);body=FreedomUi.body(this);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));root.post(()->{if(getCurrentFocus()==null)FreedomUi.first(body);});}
    private void menu(){mode="menu";generation++;layout("A little play time","Offline games, made for the remote. Nothing runs after you leave.");FreedomUi.action(this,body,"Chess · continue saved game",this::chess);FreedomUi.action(this,body,"Skyhop · one-button flight",this::skyhop);FreedomUi.action(this,body,"Daily frame · guess a title from your collection",this::daily);FreedomUi.action(this,body,"Back to Home",this::finish);}
    private void chess(){mode="chess";try{chess=FreedomChess.load(store().getString("chess",""));}catch(Exception none){chess=new FreedomChess();}drawChess();}
    private void drawChess(){generation++;layout("Chess","Arrows move · OK picks a piece / destination · You play White. Back opens the game menu.");LinearLayout row=new LinearLayout(this);body.addView(row);board=new Board(this);row.addView(board,new LinearLayout.LayoutParams(FreedomUi.dp(this,310),FreedomUi.dp(this,310)));LinearLayout side=FreedomUi.body(this);row.addView(side,new LinearLayout.LayoutParams(0,-1,1));message=FreedomUi.text(this,"",20);side.addView(message);FreedomUi.action(this,side,"New game",()->new AlertDialog.Builder(this).setTitle("Start a new game?").setNegativeButton("Cancel",null).setPositiveButton("New game",(d,w)->{chess=new FreedomChess();saveChess();drawChess();}).show());FreedomUi.action(this,side,"Computer strength · "+level,()->new AlertDialog.Builder(this).setTitle("Computer strength").setSingleChoiceItems(new String[]{"Easy","Casual","Thinking"},level-1,(d,n)->{level=n+1;d.dismiss();}).setNegativeButton("Cancel",null).show());FreedomUi.action(this,side,"Back to Play",this::menu);updateChess();board.requestFocus();if(active)think();}
    private void saveChess(){store().edit().putString("chess",chess.save()).apply();}
    private void updateChess(){if(board!=null)board.invalidate();if(message==null)return;java.util.List<FreedomChess.Move> legal=chess.legal();message.setText(legal.isEmpty()?(chess.check(chess.white)?"Checkmate · "+(chess.white?"Computer wins":"You win"):"Stalemate"):chess.drawn()?"Draw":chess.white?(chess.check(true)?"Your move · in check":"Your move"):"Computer is thinking…");}
    private void think(){if(!active||!mode.equals("chess")||chess.white||chess.drawn()||chess.legal().isEmpty())return;final int run=++generation;final FreedomChess position=chess.copy();worker.execute(()->{FreedomChess.Move move=position.choose(level,System.nanoTime()+500000000L);main.post(()->{if(!active||run!=generation||!mode.equals("chess")||move==null)return;chess.apply(move);saveChess();updateChess();});});}
    private final class Board extends View {
        final Paint paint=new Paint(3);int cursor=52,from=-1;final String[] glyph={"","♙","♘","♗","♖","♕","♔"};
        Board(Context c){super(c);setFocusable(true);setFocusableInTouchMode(true);setContentDescription("Chess board. Arrows move. OK selects a piece and destination.");}
        protected void onDraw(Canvas c){float size=Math.min(getWidth(),getHeight())/8f;List<FreedomChess.Move> legal=chess.legal();for(int i=0;i<64;i++){float x=i%8*size,y=i/8*size;paint.setColor((i+i/8)%2==0?0xffcfdae0:0xff38566b);c.drawRect(x,y,x+size,y+size,paint);if(from==i){paint.setColor(0x9955d6bf);c.drawRect(x,y,x+size,y+size,paint);}int p=chess.board[i];if(p!=0){paint.setColor(p>0?0xfffaf6e6:0xff101925);paint.setTextAlign(Paint.Align.CENTER);paint.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));paint.setTextSize(size*.86f);c.drawText(glyph[Math.abs(p)],x+size/2,y+size*.82f,paint);}if(from>=0)for(FreedomChess.Move m:legal)if(m.from==from&&m.to==i){paint.setColor(0xff12b69e);c.drawCircle(x+size/2,y+size/2,size*.1f,paint);}}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(size*.075f);paint.setColor(0xffffd480);c.drawRect(cursor%8*size+2,cursor/8*size+2,(cursor%8+1)*size-2,(cursor/8+1)*size-2,paint);paint.setStyle(Paint.Style.FILL);}
        @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_DPAD_LEFT)cursor=cursor/8*8+Math.max(0,cursor%8-1);else if(key==KeyEvent.KEYCODE_DPAD_RIGHT)cursor=cursor/8*8+Math.min(7,cursor%8+1);else if(key==KeyEvent.KEYCODE_DPAD_UP)cursor=Math.max(0,cursor-8);else if(key==KeyEvent.KEYCODE_DPAD_DOWN)cursor=Math.min(63,cursor+8);else if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(!chess.white||chess.drawn())return true;List<FreedomChess.Move> options=new ArrayList<>();for(FreedomChess.Move m:chess.legal())if(m.from==from&&m.to==cursor)options.add(m);if(!options.isEmpty()){if(options.size()>1){new AlertDialog.Builder(FreedomPlayActivity.this).setTitle("Promote pawn").setItems(new String[]{"Queen","Rook","Bishop","Knight"},(d,n)->move(options.get(n))).show();}else move(options.get(0));}else from=chess.board[cursor]>0?cursor:-1;}else return super.onKeyDown(key,event);setContentDescription("Chess square "+(char)('a'+cursor%8)+(8-cursor/8));invalidate();return true;}
        private void move(FreedomChess.Move move){chess.apply(move);from=-1;saveChess();updateChess();think();}
    }
    private void skyhop(){mode="sky";generation++;layout("Skyhop","OK starts and lifts your light. Pass between the towers. Back pauses and opens the menu.");sky=new Skyhop(this);body.addView(sky,new LinearLayout.LayoutParams(-1,FreedomUi.dp(this,290)));sky.requestFocus();}
    private final class Skyhop extends View {
        final Paint p=new Paint(3);final Random random=new Random();final float[] x={1.1f,1.5f,1.9f},gap={.45f,.6f,.38f};float y=.5f,velocity;int score;boolean running,dead;long last;int best=store().getInt("sky-best",0);
        Skyhop(Context c){super(c);setFocusable(true);setFocusableInTouchMode(true);setContentDescription("Skyhop. Press OK to start or lift your light.");}
        protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setShader(new LinearGradient(0,0,0,h,0xff183b58,0xff080f1e,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);long now=System.nanoTime();float dt=Math.min(.04f,last==0?0:(now-last)/1e9f);last=now;if(running&&active&&hasWindowFocus()){velocity+=dt*.75f;y+=velocity*dt;for(int i=0;i<x.length;i++){float before=x[i];x[i]-=dt*.18f;if(before>.25f&&x[i]<=.25f)score++;if(x[i]<-.1f){x[i]=1.12f;gap[i]=.3f+random.nextFloat()*.4f;}if(Math.abs(x[i]-.25f)<.055f&&(y<gap[i]-.16f||y>gap[i]+.16f))dead=true;}if(y<.03f||y>.97f)dead=true;if(dead){running=false;best=Math.max(best,score);store().edit().putInt("sky-best",best).apply();}}
            p.setColor(0xff487b84);for(int i=0;i<x.length;i++){c.drawRoundRect(w*x[i],0,w*(x[i]+.065f),h*(gap[i]-.16f),8,8,p);c.drawRoundRect(w*x[i],h*(gap[i]+.16f),w*(x[i]+.065f),h,8,8,p);}p.setColor(0xffffd582);c.drawCircle(w*.25f,h*y,h*.025f,p);p.setColor(0xffeff6fc);p.setTextAlign(Paint.Align.LEFT);p.setTextSize(h*.07f);c.drawText("Score "+score+"   ·   Best "+best,w*.035f,h*.1f,p);if(!running)c.drawText(dead?"OK to try again":"OK to start",w*.37f,h*.5f,p);if(running&&active&&hasWindowFocus())postInvalidateDelayed(33);}
        public boolean onKeyDown(int key,KeyEvent e){if(key!=23&&key!=66)return super.onKeyDown(key,e);if(e.getRepeatCount()>0)return true;if(!running){dead=false;y=.5f;score=0;x[0]=1.1f;x[1]=1.5f;x[2]=1.9f;last=0;running=true;}velocity=-.32f;invalidate();return true;}
    }
    private void daily(){mode="daily";generation++;CinemaSpec s=CinemaStore.read(this);List<CinemaSpec.Title> choices=new ArrayList<>();for(CinemaSpec.Title t:s.titles)if(FamilyMode.allowed(this,t.pkg)&&CinemaAssets.read(this,t.backdrop.isEmpty()?t.poster:t.backdrop)!=null)choices.add(t);layout("Daily frame","Guess a title from your own artwork. Six guesses reveal more of the picture.");if(choices.size()<2){FreedomUi.action(this,body,"Add artwork to at least two collection titles",()->CinemaActivity.open(this,"titles"));FreedomUi.action(this,body,"Back to Play",this::menu);return;}choices.sort(Comparator.comparing(t->t.id));long day=LocalDate.now().toEpochDay();CinemaSpec.Title answer=choices.get((int)Math.floorMod(day,choices.size()));String key="daily-"+day+"-"+answer.id;int guesses=store().getInt(key,0);boolean won=store().getBoolean(key+"-won",false);Frame image=new Frame(this,CinemaAssets.read(this,answer.backdrop.isEmpty()?answer.poster:answer.backdrop),Math.min(6,guesses),won);body.addView(image,new LinearLayout.LayoutParams(-1,FreedomUi.dp(this,210)));TextView progress=FreedomUi.text(this,won?"Correct · "+answer.name:guesses>=6?"Today's title: "+answer.name:"Guess "+(guesses+1)+" of 6",20);body.addView(progress);
        if(!won&&guesses<6)for(CinemaSpec.Title t:choices)FreedomUi.action(this,body,t.name,()->{store().edit().putInt(key,guesses+1).putBoolean(key+"-won",t.id.equals(answer.id)).apply();daily();});FreedomUi.action(this,body,"Back to Play",this::menu);}
    static final class Frame extends View{final Bitmap bitmap;final int step;final boolean won;final Paint p=new Paint(3);Frame(Context c,Bitmap b,int n,boolean w){super(c);bitmap=b;step=n;won=w;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas c){if(bitmap==null)return;float k=won||step>=6?1:Math.max(.23f,(step+1)/6f);int w=(int)(bitmap.getWidth()*k),h=(int)(bitmap.getHeight()*k);Rect src=new Rect((bitmap.getWidth()-w)/2,(bitmap.getHeight()-h)/2,(bitmap.getWidth()+w)/2,(bitmap.getHeight()+h)/2);c.drawBitmap(bitmap,src,new RectF(0,0,getWidth(),getHeight()),p);}}
    @Override public void onBackPressed(){if(mode.equals("menu")){finish();return;}if(sky!=null)sky.running=false;new AlertDialog.Builder(this).setTitle("Paused").setItems(new String[]{"Continue","Back to Play"},(d,n)->{if(n==1)menu();else if(sky!=null){sky.last=0;sky.running=!sky.dead;sky.invalidate();}}).setNegativeButton("Continue",null).show();}
    @Override protected void onResume(){super.onResume();active=true;if(!profile.equals(ProfileStore.id())){finish();return;}if(mode.equals("chess"))think();}
    @Override protected void onPause(){active=false;generation++;if(sky!=null)sky.running=false;super.onPause();}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();main.removeCallbacksAndMessages(null);super.onDestroy();}
}
